const pptxgen = require("pptxgenjs");
const pres = new pptxgen();

pres.layout = "LAYOUT_16x9";
pres.title = "AI Model Landscape April 2026";
pres.author = "Artificial Analysis";

const colors = {
  primary: "1E2761",
  secondary: "CADCFC",
  accent: "FFFFFF",
  darkBg: "0F1629",
  lightBg: "F8FAFC",
  cardBg: "FFFFFF",
  muted: "64748B",
  accentColor: "3B82F6",
  highlight: "F59E0B",
  negative: "EF4444",
  positive: "10B981"
};

const makeShadow = () => ({ type: "outer", blur: 4, offset: 2, angle: 135, color: "000000", opacity: 0.1 });

// Slide 1: Title - dark background, clean layout
let slide1 = pres.addSlide();
slide1.background = { color: colors.darkBg };

slide1.addText("AI Model Landscape", { x: 0.8, y: 1.8, w: 8.4, h: 0.9, fontSize: 42, bold: true, color: colors.accent, fontFace: "Arial Black" });
slide1.addText("April 2026", { x: 0.8, y: 2.65, w: 8.4, h: 0.55, fontSize: 30, color: colors.secondary, fontFace: "Calibri" });
slide1.addText("Benchmarking Intelligence, Speed, and Cost Across 11 Frontier Models", { x: 0.8, y: 3.4, w: 8.4, h: 0.45, fontSize: 16, color: colors.muted, fontFace: "Calibri" });

slide1.addShape(pres.shapes.RECTANGLE, { x: 0.8, y: 4.1, w: 0.6, h: 0.05, fill: { color: colors.accentColor } });

slide1.addText("Source: Artificial Analysis | April 2026", { x: 0.8, y: 4.9, w: 5, h: 0.25, fontSize: 11, color: colors.muted, fontFace: "Calibri" });
slide1.addText("For: AI Engineering Leads & Product Managers", { x: 0.8, y: 5.15, w: 5, h: 0.25, fontSize: 11, color: colors.muted, fontFace: "Calibri" });

// Slide 2: Intelligence - Full 11-model ranking table
let slide2 = pres.addSlide();
slide2.background = { color: colors.lightBg };

slide2.addText("Gemini 3.1 Pro Preview and GPT-5.4 Co-Lead the Intelligence Index at 57", { x: 0.6, y: 0.3, w: 8.8, h: 0.55, fontSize: 20, bold: true, color: colors.primary, fontFace: "Arial" });

const intelData = [
  [{ text: "#", options: { bold: true, fill: { color: colors.primary }, color: "FFFFFF" } },
   { text: "Model", options: { bold: true, fill: { color: colors.primary }, color: "FFFFFF" } },
   { text: "Provider", options: { bold: true, fill: { color: colors.primary }, color: "FFFFFF" } },
   { text: "Score", options: { bold: true, fill: { color: colors.primary }, color: "FFFFFF" } }],
  [{ text: "1", options: { fill: { color: "FEF3C7" } } }, { text: "Gemini 3.1 Pro Preview", options: { fill: { color: "FEF3C7" }, bold: true } }, { text: "Google", options: { fill: { color: "FEF3C7" } } }, { text: "57", options: { fill: { color: "FEF3C7" }, bold: true } }],
  [{ text: "2", options: { fill: { color: "FEF3C7" } } }, { text: "GPT-5.4 (xhigh)", options: { fill: { color: "FEF3C7" }, bold: true } }, { text: "OpenAI", options: { fill: { color: "FEF3C7" } } }, { text: "57", options: { fill: { color: "FEF3C7" }, bold: true } }],
  [{ text: "3", options: {} }, { text: "Claude Opus 4.6 (max)", options: {} }, { text: "Anthropic", options: {} }, { text: "53", options: {} }],
  [{ text: "4", options: {} }, { text: "Muse Spark", options: {} }, { text: "Meta", options: {} }, { text: "52", options: {} }],
  [{ text: "5", options: {} }, { text: "Claude Sonnet 4.6 (max)", options: {} }, { text: "Anthropic", options: {} }, { text: "52", options: {} }],
  [{ text: "6", options: {} }, { text: "GLM-5.1", options: {} }, { text: "Z AI", options: {} }, { text: "51", options: {} }],
  [{ text: "7", options: {} }, { text: "Grok 4.20 0309 v2", options: {} }, { text: "xAI", options: {} }, { text: "49", options: {} }],
  [{ text: "8", options: {} }, { text: "Gemini 3 Flash", options: {} }, { text: "Google", options: {} }, { text: "46", options: {} }],
  [{ text: "9", options: {} }, { text: "DeepSeek V3.2", options: {} }, { text: "DeepSeek", options: {} }, { text: "42", options: {} }],
  [{ text: "10", options: {} }, { text: "NVIDIA Nemotron 3 Super", options: {} }, { text: "NVIDIA", options: {} }, { text: "36", options: {} }],
  [{ text: "11", options: {} }, { text: "gpt-oss-120B (high)", options: {} }, { text: "OpenAI", options: {} }, { text: "33", options: {} }]
];

slide2.addTable(intelData, {
  x: 0.5, y: 1.0, w: 9, h: 4.0,
  colW: [0.5, 4.0, 2.3, 1.5],
  fontSize: 12,
  fontFace: "Calibri",
  color: colors.primary,
  border: { pt: 0.5, color: "E2E8F0" },
  align: "center",
  valign: "middle"
});

slide2.addText("Score range: 33-57  |  11 models evaluated  |  Source: Artificial Analysis Intelligence Index, April 2026", { x: 0.5, y: 5.15, w: 9, h: 0.25, fontSize: 10, color: colors.muted, fontFace: "Calibri" });

// Slide 3: Speed - output tokens per second
let slide3 = pres.addSlide();
slide3.background = { color: colors.lightBg };

slide3.addText("gpt-oss-120B Tops Output Speed at 218 Tokens/s — More Than 4x Faster Than Claude Opus 4.6", { x: 0.6, y: 0.3, w: 8.8, h: 0.55, fontSize: 18, bold: true, color: colors.primary, fontFace: "Arial" });

const speedData = [
