  [{ text: "2", options: { fill: { color: "DCFCE7" } } }, { text: "Grok 4.20 0309 v2", options: { fill: { color: "DCFCE7" }, bold: true } }, { text: "188", options: { fill: { color: "DCFCE7" }, bold: true, color: colors.positive } }],
