  [{ text: "9", options: {} }, { text: "Claude Opus 4.6 (max)", options: {} }, { text: "49", options: {} }],
  [{ text: "10", options: {} }, { text: "DeepSeek V3.2", options: {} }, { text: "46", options: {} }]
