  fontSize: 13,
  fontFace: "Calibri",
  color: colors.primary,
  border: { pt: 0.5, color: "E2E8F0" },
  align: "center",
  valign: "middle"
});

slide3.addText("Open-weight models dominate throughput  |  Muse Spark excluded (no speed data)  |  Source: Artificial Analysis, April 2026", { x: 0.5, y: 4.9, w: 9, h: 0.25, fontSize: 10, color: colors.muted, fontFace: "Calibri" });

// Slide 4: Pricing
let slide4 = pres.addSlide();
slide4.background = { color: colors.lightBg };

slide4.addText("From $0.30 to $10 per Million Tokens: A 33x Pricing Gap Across Models", { x: 0.6, y: 0.3, w: 8.8, h: 0.55, fontSize: 18, bold: true, color: colors.primary, fontFace: "Arial" });

const pricingData = [
  [{ text: "#", options: { bold: true, fill: { color: colors.primary }, color: "FFFFFF" } },
   { text: "Model", options: { bold: true, fill: { color: colors.primary }, color: "FFFFFF" } },
